const body = $input.first().json.body || $input.first().json;

let telefono = '';
let mensaje = '';
let nombre = '';
let remoteJid = '';

if (body.data) {
  const key = body.data.key || {};
  remoteJid = key.remoteJidAlt || key.remoteJid || '';
  telefono = remoteJid.split('@')[0];

  mensaje = body.data.message?.conversation ||
            body.data.message?.extendedTextMessage?.text ||
            '';

  nombre = body.data.pushName || '';
} else {
  telefono = body.telefono || body.from || body.sender || '';
  mensaje = body.mensaje || body.message || body.text || '';
  nombre = body.nombre || body.pushName || '';
  remoteJid = telefono ? telefono + '@s.whatsapp.net' : '';
}

return [
  {
    json: {
      telefono: telefono.replace(/[^0-9]/g, ''),
      mensaje: mensaje.trim(),
      nombre: nombre,
      remoteJid: remoteJid
    }
  }
];

const mensaje = $json.mensaje;
const prompt = 'Eres un clasificador de mensajes para un taller de motos.\nClasifica el siguiente mensaje en UNA categoría:\n- AGENDAMIENTO\n- COTIZACION\n- DIAGNOSTICO\n- INFORMACION\n- QUEJA\n\nResponde SOLO la categoría en mayúsculas.\n\nMensaje: ' + mensaje;

return [{
  json: {
    telefono: $json.telefono,
    mensaje: mensaje,
    nombre: $json.nombre,
    gemini_prompt: prompt
  }
}];

const prompt = $json.gemini_prompt;

let candidates = [];
try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=$env.GEMINI_API_KEY',
    headers: {
      'Content-Type': 'application/json'
    },
    body: {
      contents: [{ parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.1, maxOutputTokens: 300 }
    }
  });
  candidates = response.candidates || [];
} catch (error) {
  candidates = [{ content: { parts: [{ text: 'INFORMACION (error: ' + error.message + ')' }] } }];
}

return [{
  json: {
    telefono: $json.telefono,
    mensaje: $json.mensaje,
    nombre: $json.nombre,
    candidates: candidates
  }
}];

const originalData = $json;
const geminiText = $json.candidates?.[0]?.content?.parts?.[0]?.text || '';
const match = geminiText.toUpperCase().match(/AGENDAMIENTO|COTIZACION|DIAGNOSTICO|INFORMACION|QUEJA/);
const categoria = match ? match[0] : 'INFORMACION';

return [{
  json: {
    telefono: originalData.telefono,
    mensaje: originalData.mensaje,
    nombre: originalData.nombre,
    categoria: categoria
  }
}];

const mensaje = $json.mensaje.toLowerCase();
let respuesta = '';
if (mensaje.includes('cancel')) {
  respuesta = 'Entendido. He cancelado tu cita. Si deseas agendar una nueva, solo dímelo.';
} else if (mensaje.includes('reprogram') || mensaje.includes('cambiar')) {
  respuesta = 'Claro, podemos reprogramar tu cita. ¿Qué día y hora te gustaría?';
} else if (mensaje.includes('horario') || mensaje.includes('dispon')) {
  respuesta = 'Nuestros horarios disponibles son: Lunes a Viernes de 9:00 a 18:00 y Sábados de 9:00 a 14:00. ¿Qué día prefieres?';
} else {
  respuesta = 'Con gusto te ayudo a agendar una cita. ¿Qué servicio necesitas y qué día te gustaría venir?';
}
return [{ json: { ...$json, respuesta } }];

const mensaje = $json.mensaje.toLowerCase();
let respuesta = '';
if (mensaje.includes('aceite')) {
  respuesta = '🛵 *Cambio de Aceite*: $350 MXN (incluye aceite y filtro).';
} else if (mensaje.includes('freno')) {
  respuesta = '🛵 *Servicio de Frenos*: Balatas desde $250, rectificación de disco $400, purga de líquido $150.';
} else if (mensaje.includes('llanta')) {
  respuesta = '🛵 *Llantas*: Trasera desde $800, Delantera desde $700 (instalación incluida).';
} else if (mensaje.includes('cadena') || mensaje.includes('transmisi')) {
  respuesta = '🛵 *Cadena y Transmisión*: Ajuste $100, lubricación $150, cambio de kit $1,200.';
} else if (mensaje.includes('bater')) {
  respuesta = '🛵 *Batería*: Desde $600 (instalación incluida).';
} else {
  respuesta = '🛵 *Lista de Precios:*\n- Cambio de Aceite: $350\n- Frenos: desde $250\n- Llantas: desde $700\n- Cadena/Transmisión: desde $100\n- Batería: desde $600\n- Diagnóstico General: $200\n\n¿Sobre qué servicio deseas más detalles?';
}
return [{ json: { ...$json, respuesta } }];

const mensaje = $json.mensaje.toLowerCase();
let respuesta = '';
if (mensaje.includes('ruido') || mensaje.includes('chilla') || mensaje.includes('traquetea')) {
  respuesta = 'Entiendo que escuchas un ruido anormal. ¿Podrías describir si el ruido ocurre al acelerar, frenar, o en curvas?';
} else if (mensaje.includes('no enciende') || mensaje.includes('no prende') || mensaje.includes('arranca')) {
  respuesta = 'Lamento que no encienda. ¿Escuchas algún clic cuando intentas encender? ¿Las luces del tablero se encienden normalmente?';
} else if (mensaje.includes('fuga') || mensaje.includes('pierde') || mensaje.includes('gotea')) {
  respuesta = 'Una fuga puede ser peligrosa. Te recomendamos no usarla hasta revisarla. ¿De qué color es el líquido?';
} else if (mensaje.includes('vibra') || mensaje.includes('tiembla') || mensaje.includes('sacude')) {
  respuesta = 'Las vibraciones pueden tener varias causas. ¿Ocurren al acelerar, al frenar o al mantener velocidad constante?';
} else {
  respuesta = 'Gracias por reportar la falla. Para un mejor diagnóstico, ¿podrías contarme más detalles? ¿Cuándo comenzó el problema?';
}
return [{ json: { ...$json, respuesta } }];

const mensaje = $json.mensaje.toLowerCase();
let respuesta = '';
if (mensaje.includes('horario') || mensaje.includes('abren') || mensaje.includes('cierran')) {
  respuesta = '📍 *Horarios:* Lunes a Viernes: 9:00 a 18:00, Sábados: 9:00 a 14:00, Domingos: Cerrado';
} else if (mensaje.includes('ubicaci') || mensaje.includes('direcci') || mensaje.includes('dónde')) {
  respuesta = '📍 *Dirección:* Calle Benito Juárez #123, Col. Centro, Huajuapan de León, Oax.';
} else if (mensaje.includes('pago') || mensaje.includes('tarjeta') || mensaje.includes('efectivo')) {
  respuesta = '💳 *Formas de Pago:* Efectivo, Tarjeta débito/crédito, Transferencia, Mercado Pago';
} else if (mensaje.includes('tiempo') || mensaje.includes('demora') || mensaje.includes('tarda')) {
  respuesta = '⏱️ *Tiempos:* Cambio Aceite 30min, Frenos 1-2h, Diagnóstico 30min-1h, Servicio completo 2-4h';
} else {
  respuesta = '👋 ¡Bienvenido a Moto Servicios Timón!\n📍 Benito Juárez #123, Col. Centro\n🕐 Lun-Vie 9:00-18:00, Sáb 9:00-14:00\n\n¿En qué puedo ayudarte?';
}
return [{ json: { ...$json, respuesta } }];

const nombre = $json.nombre || 'cliente';
const respuesta = 'Hola ' + nombre + ', lamentamos mucho tu experiencia. 😔

Hemos registrado tu queja y la revisaremos con nuestro equipo.

Un asesor te contactará en máximo 24 horas hábiles.

Gracias por tu paciencia y confianza en Moto Servicios Timón.';
return [{ json: { ...$json, respuesta } }];

function esc(str) {
  return (str || '').replace(/'/g, "''").replace(/\\/g, '\\\\');
}

return [{
  json: {
    telefono: $json.telefono,
    mensaje: $json.mensaje,
    nombre: $json.nombre,
    respuesta: $json.respuesta,
    categoria: $json.categoria,
    telefono_esc: esc($json.telefono),
    mensaje_esc: esc($json.mensaje),
    nombre_esc: esc($json.nombre || 'Cliente'),
    respuesta_esc: esc($json.respuesta)
  }
}];

// Enviar respuesta a WhatsApp usando Evolution API
const telefono = $json.telefono;
const respuesta = $json.respuesta;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'http://evolution:8080/message/sendText/timonws',
    headers: {
      'apikey': '$env.AUTHENTICATION_API_KEY',
      'Content-Type': 'application/json'
    },
    body: {
      number: telefono,
      text: respuesta
    }
  });
  return [{ json: { success: true, categoria: $json.categoria, respuesta: respuesta, evolutionResponse: response } }];
} catch (error) {
  return [{ json: { success: false, categoria: $json.categoria, respuesta: respuesta, error: error.message } }];
}
